"use strict";
const absFloor = require("./absFloor-CImRXpov.js");
const constants = require("./constants-DR3SPJ7u.js");
const parse = require("./parse.js");
function diffInDays(date, input, asFloat) {
  const parsed = parse(input);
  const output = (+date - +parsed) / constants.MS_IN_DAY;
  return asFloat ? output : absFloor.absFloor(output);
}
module.exports = diffInDays;
